files.content:
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: #2d1b69;
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 18px;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  padding: 16px;
}

.quiz-card {
  background: #f0e6d2;
  border: 4px solid #4a3f6b;
  border-radius: 16px;
  padding: 32px 24px;
  max-width: 480px;
  width: 100%;
  text-align: center;
  box-shadow: 8px 8px 0 #1a103a;
  image-rendering: pixelated;
}

h1 {
  color: #2d1b69;
  font-size: 28px;
  margin-bottom: 24px;
  text-transform: uppercase;
  letter-spacing: 2px;
}

.question {
  background: #fff8e7;
  border: 3px solid #4a3f6b;
  border-radius: 8px;
  padding: 24px 16px;
  font-size: 32px;
  font-weight: bold;
  color: #2d1b69;
  margin-bottom: 24px;
  min-height: 100px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.answers {
  display: flex;
  gap: 16px;
  margin-bottom: 24px;
}

.answer-btn {
  flex: 1;
  padding: 20px 0;
  font-size: 24px;
  font-weight: bold;
  background: #e8d5b5;
  border: 3px solid #4a3f6b;
  border-radius: 8px;
  color: #2d1b69;
  cursor: pointer;
  transition: background 0.1s, transform 0.1s, box-shadow 0.1s;
  box-shadow: 4px 4px 0 #4a3f6b;
}

.answer-btn:hover:not(:disabled) {
  background: #f5e6cc;
}

.answer-btn:focus-visible {
  outline: 3px solid #ffb347;
  outline-offset: 2px;
}

.answer-btn:active:not(:disabled) {
  transform: translate(2px, 2px);
  box-shadow: 2px 2px 0 #4a3f6b;
}

.answer-btn:disabled {
  opacity: 0.6;
  cursor: not-allowed;
  box-shadow: none;
  transform: none;
}

.score-display {
  font-size: 22px;
  color: #2d1b69;
  margin-bottom: 24px;
  font-weight: bold;
}

#score {
  font-size: 28px;
  color: #8b5cf6;
}

.controls {
  display: flex;
  gap: 16px;
}

.control-btn {
  flex: 1;
  padding: 16px 0;
  font-size: 20px;
  font-weight: bold;
  background: #8b5cf6;
  border: 3px solid #4a3f6b;
  border-radius: 8px;
  color: #fff;
  cursor: pointer;
  transition: background 0.1s, transform 0.1s, box-shadow 0.1s;
  box-shadow: 4px 4px 0 #4a3f6b;
}

.control-btn:hover:not(:disabled) {
  background: #9d7bff;
}

.control-btn:focus-visible {
  outline: 3px solid #ffb347;
  outline-offset: 2px;
}

.control-btn:active:not(:disabled) {
  transform: translate(2px, 2px);
  box-shadow: 2px 2px 0 #4a3f6b;
}

.control-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
  box-shadow: none;
  transform: none;
}

@media (max-width: 400px) {
  body {
    font-size: 16px;
  }
  h1 {
    font-size: 24px;
  }
  .question {
    font-size: 26px;
    padding: 20px 12px;
  }
  .answer-btn {
    font-size: 20px;
    padding: 16px 0;
  }
  .control-btn {
    font-size: 18px;
    padding: 14px 0;
  }
}

[hidden] {
  display: none !important;
}

const questionEl = document.getElementById('question');
const answerA = document.getElementById('answer-a');
const answerB = document.getElementById('answer-b');
const scoreEl = document.getElementById('score');
const nextBtn = document.getElementById('next');
const restartBtn = document.getElementById('restart');

let currentQuestion = 0;
let score = 0;
let answered = false;

const questions = [
  { text: '2 + 2 = ?', a: '4', b: '5', correct: 'a' },
  { text: '3 + 3 = ?', a: '5', b: '6', correct: 'b' }
];

function updateDisplay() {
  questionEl.textContent = questions[currentQuestion].text;
  answerA.textContent = questions[currentQuestion].a;
  answerB.textContent = questions[currentQuestion].b;
  scoreEl.textContent = score;
  answerA.disabled = false;
  answerB.disabled = false;
  nextBtn.disabled = true;
  answered = false;
}

function handleAnswer(choice) {
  if (answered) return;
  answered = true;
  answerA.disabled = true;
  answerB.disabled = true;
  nextBtn.disabled = false;
  if (choice === questions[currentQuestion].correct) {
    score++;
    scoreEl.textContent = score;
  }
}

function handleNext() {
  if (currentQuestion < questions.length - 1) {
    currentQuestion++;
    updateDisplay();
  } else {
    questionEl.textContent = 'Finished';
    answerA.disabled = true;
    answerB.disabled = true;
    nextBtn.disabled = true;
  }
}

function handleRestart() {
  currentQuestion = 0;
  score = 0;
  updateDisplay();
}

answerA.addEventListener('click', () => handleAnswer('a'));
answerB.addEventListener('click', () => handleAnswer('b'));
nextBtn.addEventListener('click', handleNext);
restartBtn.addEventListener('click', handleRestart);

// Initialize
updateDisplay();
